#!/usr/bin/env bash
# Refresh the copy of the OpenAPI contract that the API binary embeds.
#
# contracts/openapi.yaml at the repository root is the canonical document. Go's
# embed directive cannot reach outside the module, so services/api keeps a copy.
# That copy is generated by this script, never edited by hand.
#
#   ./scripts/sync-contracts.sh          copy the contract into the module
#   ./scripts/sync-contracts.sh --check  fail if the copy has drifted (CI)
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
src="$root/contracts/openapi.yaml"
dst="$root/services/api/internal/contracts/openapi.yaml"

if [[ ! -f "$src" ]]; then
  echo "missing canonical contract: $src" >&2
  exit 1
fi

if [[ "${1:-}" == "--check" ]]; then
  if ! cmp -s "$src" "$dst"; then
    echo "contract drift: $dst is out of date." >&2
    echo "run ./scripts/sync-contracts.sh and commit the result." >&2
    exit 1
  fi
  echo "contract in sync"
  exit 0
fi

cp "$src" "$dst"
echo "synced $dst from contracts/openapi.yaml"
